import json, os, re, math, datetime, subprocess
from collections import deque


class Memory:
    def __init__(self, max_short=20):
        self.short_term = deque(maxlen=max_short)
        self.long_term = []
        self.summary = ""

    def add(self, content, role="system"):
        self.short_term.append({"role": role, "content": content,
            "timestamp": datetime.datetime.now().isoformat()})

    def recall(self, query, top_k=3):
        if not self.long_term:
            return []
        qw = set(query.lower().split())
        scored = [(len(qw & set(e["content"].lower().split())), e["content"])
                  for e in self.long_term]
        scored.sort(key=lambda x: -x[0])
        return [c for _, c in scored[:top_k]]

    def archive(self, content):
        self.long_term.append({"content": content,
            "timestamp": datetime.datetime.now().isoformat()})

    def get_context(self, limit=10):
        recent = [e["content"] for e in list(self.short_term)[-limit:]]
        archived = self.recall(self.summary, top_k=3)
        return "\n".join(recent + archived) if recent or archived else "No memory."


class ToolRegistry:
    def __init__(self):
        self.tools = {}

    def register(self, name, func, description=""):
        self.tools[name] = {"func": func, "desc": description}

    def execute(self, name, **kwargs):
        if name not in self.tools:
            return f"Error: Unknown tool '{name}'"
        try:
            return self.tools[name]["func"](**kwargs)
        except Exception as e:
            return f"Tool error: {e}"

    def list_tools(self):
        return {n: t["desc"] for n, t in self.tools.items()}
